    87	/// C's `git__is_ssizet(p)` converts its `size_t` to `ssize_t` and back, which keeps every
    88	/// value: it is true for every `p`. This function refuses a `p` past `isize::MAX`, which the
    89	/// C's callers mean it to, as the module's docs describe.
    90	///
    91	/// ```
    92	/// use libgit2_crustify::libgit2::src::util::integer_h::fits_isize;
    93	///
    94	/// assert!(fits_isize(isize::MAX.unsigned_abs()));
    95	/// assert!(!fits_isize(usize::MAX));
    96	/// ```
    97	///
    98	/// Replaces `fn::git__is_ssizet`
    99	#[doc(alias = "git__is_ssizet")]
   100	#[must_use]
   101	#[inline]
   102	pub fn fits_isize<T: TryInto<isize>>(value: T) -> bool {
   103	    value.try_into().is_ok()
   104	}
   105	
   106	/// Whether `value` is in `u16`'s range.
   107	///
   108	/// C's `git__is_uint16(p)` takes a `size_t`, whose round trip through `uint16_t` keeps
   109	/// exactly the values in that range: for a `usize`, this is its answer.
   110	///
   111	/// ```
   112	/// use libgit2_crustify::libgit2::src::util::integer_h::fits_u16;
   113	///
   114	/// assert!(fits_u16(65_535_usize));
   115	/// assert!(!fits_u16(65_536_usize));
   116	/// ```
   117	///
   118	/// Replaces `fn::git__is_uint16`
   119	#[doc(alias = "git__is_uint16")]
   120	#[must_use]
   121	#[inline]
   122	pub fn fits_u16<T: TryInto<u16>>(value: T) -> bool {
   123	    value.try_into().is_ok()
   124	}
