   126	/// Whether `value` is in `u32`'s range.
   127	///
   128	/// C's `git__is_uint32(p)` takes a `size_t`, whose round trip through `uint32_t` keeps
   129	/// exactly the values in that range: for a `usize`, this is its answer.
   130	///
   131	/// ```
   132	/// use libgit2_crustify::libgit2::src::util::integer_h::fits_u32;
   133	///
   134	/// assert!(fits_u32(4_294_967_295_usize));
   135	/// assert!(!fits_u32(4_294_967_296_usize));
