   138	/// Replaces `fn::git__is_uint32`
   139	#[doc(alias = "git__is_uint32")]
   140	#[must_use]
   141	#[inline]
   142	pub fn fits_u32<T: TryInto<u32>>(value: T) -> bool {
   143	    value.try_into().is_ok()
   144	}
