   147	///
   148	/// C's `git__is_ulong(p)` takes an `int64_t` and reports whether it survives the round trip
   149	/// through `unsigned long`, which on this build is 64 bits wide and keeps every value, a
   150	/// negative one included; this function refuses a negative `value`, as the module's docs
   151	/// describe. Where `unsigned long` is 32 bits wide, as on Windows, the round trip keeps
   152	/// exactly the range, which is this function's answer there too.
   153	///
   154	/// ```
   155	/// use core::ffi::c_ulong;
   156	///
   157	/// use libgit2_crustify::libgit2::src::util::integer_h::fits_c_ulong;
   158	///
   159	/// assert!(fits_c_ulong(c_ulong::MAX));
   160	/// assert!(!fits_c_ulong(-1_i64));
