   164	#[doc(alias = "git__is_ulong")]
   165	#[must_use]
   166	#[inline]
   167	pub fn fits_c_ulong<T: TryInto<c_ulong>>(value: T) -> bool {
   168	    value.try_into().is_ok()
   169	}
