   197	/// `__builtin_uaddl_overflow`; the module's docs name the other branches, which compute the
   198	/// same, and what each leaves in `out` on overflow.
   199	///
   200	/// ```
   201	/// use libgit2_crustify::libgit2::src::util::integer_h::checked_add_usize;
   202	///
   203	/// assert_eq!(checked_add_usize(42, 69), Some(111));
   204	/// assert_eq!(checked_add_usize(usize::MAX - 1, 1), Some(usize::MAX));
