   268	/// use libgit2_crustify::libgit2::src::util::integer_h::checked_sub_c_int;
   269	///
   270	/// assert_eq!(checked_sub_c_int(-1, i32::MAX), Some(i32::MIN));
   271	/// assert_eq!(checked_sub_c_int(0, i32::MIN), None);
   272	/// ```
   273	///
   274	/// Replaces `mac::git__sub_int_overflow`
   275	#[doc(alias = "git__sub_int_overflow")]
   276	#[must_use]
   277	#[inline]
   278	pub const fn checked_sub_c_int(one: c_int, two: c_int) -> Option<c_int> {
   279	    one.checked_sub(two)
   280	}
   281	
   282	/// `one + two`, or `None` when the sum overflows `i64`.
   283	///
   284	/// C's `git__add_int64_overflow(&out, one, two)` returns true on overflow, and otherwise
   285	/// false with the sum in `out`: this is its result. On this build it is
   286	/// `__builtin_add_overflow`, which takes operands of any integer type and checks the exact
   287	/// sum against `out`'s; every C caller passes `int64_t` operands, as this function takes.
   288	/// The module's docs name the other branches, which compute the same, and what each leaves
   289	/// in `out` on overflow.
   290	///
   291	/// ```
   292	/// use libgit2_crustify::libgit2::src::util::integer_h::checked_add_i64;
   293	///
   294	/// assert_eq!(checked_add_i64(i64::MIN, i64::MAX), Some(-1));
   295	/// assert_eq!(checked_add_i64(i64::MIN, -1), None);
