    20	use std::ffi::CString;
    21	
    22	use libgit2_crustify::libgit2::src::util::errors::{self, ErrorClass};
    23	use libgit2_crustify::libgit2::src::util::integer_h::{
    24	    checked_add_i64, checked_add_usize, checked_mul_i64, checked_mul_usize, fits_c_int,
    25	    fits_c_ulong, fits_isize, fits_u16, fits_u32, fits_usize,
    26	};
    27	use libgit2_crustify::sys::libgit2 as sys;
