    29	/// Takes a `git_libgit2_init` reference that is never released.
    30	fn init() {
    31	    let _ = core::mem::ManuallyDrop::new(
    32	        libgit2_crustify::libgit2::src::libgit2::libgit2::init().unwrap(),
    33	    );
    34	}
