    36	/// The `int64_t` values probed: each bound of the types the checks convert to, with its
    37	/// neighbours, and values between.
    38	fn i64_probes() -> Vec<i64> {
    39	    let mut probes = vec![0, 0x1234_5678_9ABC, -0x1234_5678_9ABC];
    40	    for bound in [
    41	        i64::MIN,
    42	        i64::MAX,
    43	        i64::from(c_int::MIN),
    44	        i64::from(c_int::MAX),
    45	        i64::from(u16::MAX),
    46	        i64::from(u32::MAX),
    47	        0,
    48	    ] {
    49	        for delta in -2..=2 {
    50	            probes.extend(bound.checked_add(delta));
    51	        }
    52	    }
    53	    probes
    54	}
    55	
    56	/// The `size_t` values probed, as [`i64_probes`].
    57	fn usize_probes() -> Vec<usize> {
    58	    let mut probes = vec![0x1234_5678];
    59	    for bound in [
    60	        0,
    61	        usize::from(u16::MAX),
    62	        usize::try_from(u32::MAX).unwrap(),
    63	        isize::MAX.unsigned_abs(),
    64	        usize::MAX,
    65	    ] {
    66	        for delta in -2_isize..=2 {
    67	            probes.extend(bound.checked_add_signed(delta));
