    73	/// `git__is_int`, `git__is_uint16` and `git__is_uint32` narrow, so their round trips keep
    74	/// their ranges: their ports agree with them on every probe.
    75	#[test]
    76	#[cfg_attr(miri, ignore = "calls C")]
    77	fn narrowing_checks_match_the_c() {
    78	    for p in i64_probes() {
    79	        // SAFETY: a pure function of its argument.
    80	        let c = unsafe { sys::git__is_int(p) } != 0;
    81	        assert_eq!(fits_c_int(p), c, "git__is_int({p})");
    82	    }
    83	    for p in usize_probes() {
    84	        // SAFETY: a pure function of its argument.
    85	        let c = unsafe { sys::git__is_uint16(p) } != 0;
    86	        assert_eq!(fits_u16(p), c, "git__is_uint16({p})");
    87	        // SAFETY: a pure function of its argument.
    88	        let c = unsafe { sys::git__is_uint32(p) } != 0;
    89	        assert_eq!(fits_u32(p), c, "git__is_uint32({p})");
    90	    }
    91	}
