    93	/// `git__is_sizet` and `git__is_ulong` agree with their ports on every non-negative
    94	/// `int64_t`, and accept every negative one, which the ports refuse; for each `uint64_t` a C
    95	/// caller passes through the parameter, the ports at its own type give the C's answer.
    96	#[test]
    97	#[cfg_attr(miri, ignore = "calls C")]
    98	fn widening_checks_match_the_c_but_for_negative_values() {
    99	    for p in i64_probes() {
   100	        // SAFETY: a pure function of its argument.
   101	        let sizet = unsafe { sys::git__is_sizet(p) } != 0;
   102	        // SAFETY: a pure function of its argument.
   103	        let ulong = unsafe { sys::git__is_ulong(p) } != 0;
   104	        if p >= 0 {
   105	            assert_eq!(fits_usize(p), sizet, "git__is_sizet({p})");
   106	            assert_eq!(fits_c_ulong(p), ulong, "git__is_ulong({p})");
   107	        } else {
   108	            assert!(sizet && !fits_usize(p), "git__is_sizet({p})");
   109	            assert!(ulong && !fits_c_ulong(p), "git__is_ulong({p})");
   110	        }
   111	    }
   112	    for p in usize_probes()
   113	        .into_iter()
   114	        .map(|p| u64::try_from(p).unwrap())
   115	    {
   116	        // SAFETY: a pure function of its argument.
   117	        let sizet = unsafe { sys::git__is_sizet(p.cast_signed()) } != 0;
   118	        // SAFETY: a pure function of its argument.
   119	        let ulong = unsafe { sys::git__is_ulong(p.cast_signed()) } != 0;
   120	        assert_eq!(fits_usize(p), sizet, "git__is_sizet({p}_u64)");
   121	        assert_eq!(fits_c_ulong(p), ulong, "git__is_ulong({p}_u64)");
   122	        assert_eq!(c_ulong::try_from(p).is_ok(), ulong);
   123	    }
   124	}
