   126	/// `git__is_ssizet` accepts every `size_t`; its port agrees up to `SSIZE_MAX` and refuses
   127	/// the rest.
   128	#[test]
   129	#[cfg_attr(miri, ignore = "calls C")]
   130	fn ssizet_check_matches_the_c_up_to_ssize_max() {
   131	    for p in usize_probes() {
   132	        // SAFETY: a pure function of its argument.
   133	        let c = unsafe { sys::git__is_ssizet(p) } != 0;
