   146	/// The `(nelem, elsize)` pairs whose product overflows or is at most [`SMALL`] bytes: every
   147	/// other one is a request the allocator may refuse for its size alone.
   148	fn array_sizes() -> Vec<(usize, usize)> {
   149	    let edges = [
   150	        0,
   151	        1,
   152	        2,
   153	        3,
   154	        0x100,
   155	        SMALL,
   156	        0xFFFF_FFFF,
   157	        0x1_0000_0000,
   158	        0x1_0000_0001,
   159	        usize::MAX / 2,
   160	        usize::MAX / 2 + 1,
   161	        usize::MAX / 3 + 1,
   162	        usize::MAX - 1,
   163	        usize::MAX,
   164	    ];
   165	    let mut pairs = Vec::new();
   166	    for nelem in edges {
   167	        for elsize in edges {
   168	            if checked_mul_usize(nelem, elsize).is_none_or(|bytes| bytes <= SMALL) {
   169	                pairs.push((nelem, elsize));
   170	            }
   171	        }
   172	    }
