   176	/// Whether the C refused a request as out of memory: a NULL result, with
   177	/// `GIT_ERROR_NOMEMORY` left as the thread's last error. A block it returns is released.
   178	fn refused(block: *mut core::ffi::c_void) -> bool {
   179	    if block.is_null() {
   180	        assert_eq!(errors::last().class(), Some(ErrorClass::NoMemory));
   181	        return true;
   182	    }
   183	    // SAFETY: `block` is a live allocation of libgit2's allocator, given up here.
   184	    unsafe { sys::git__free(block) };
   185	    false
   186	}
   187	
   188	/// `git__calloc`, `git__mallocarray` and `git__reallocarray(NULL, …)` refuse exactly the
   189	/// products `checked_mul_usize` reports as overflowing.
   190	#[test]
   191	#[cfg_attr(miri, ignore = "calls libgit2")]
   192	fn array_allocations_refuse_the_overflowing_products() {
   193	    init();
   194	    for (nelem, elsize) in array_sizes() {
   195	        let overflows = checked_mul_usize(nelem, elsize).is_none();
   196	        errors::clear();
   197	        // SAFETY: any sizes are accepted; an overflowing product is refused before any
   198	        // allocation, and any other is at most `SMALL` bytes.
   199	        let block = unsafe { sys::git__calloc(nelem, elsize) };
   200	        assert_eq!(refused(block), overflows, "git__calloc({nelem}, {elsize})");
   201	        errors::clear();
   202	        // SAFETY: as above.
   203	        let block = unsafe { sys::git__mallocarray(nelem, elsize) };
   204	        assert_eq!(
   205	            refused(block),
   206	            overflows,
   207	            "git__mallocarray({nelem}, {elsize})"
   208	        );
   209	        errors::clear();
   210	        // SAFETY: as above; a NULL block resizes no live allocation.
   211	        let block = unsafe { sys::git__reallocarray(core::ptr::null_mut(), nelem, elsize) };
   212	        assert_eq!(
   213	            refused(block),
   214	            overflows,
   215	            "git__reallocarray(NULL, {nelem}, {elsize})"
   216	        );
