   250	/// `git_config_parse_int64(value)`: the integer the C parses, or `None` where it fails.
   251	fn c_parse_int64(value: &CStr) -> Option<i64> {
   252	    let mut out = 0_i64;
   253	    // SAFETY: `value` is a live NUL-terminated string and `out` a live `int64_t`, both
   254	    // borrowed for the call.
   255	    let rc = unsafe { sys::git_config_parse_int64(&raw mut out, value.as_ptr()) };
   256	    (rc == 0).then_some(out)
   257	}
   258	
   259	/// `git_config_parse_int64`'s arithmetic over a string of a sign, digits and a unit suffix,
   260	/// as the C does it, each step through a port: `git__strntol64` takes the base from the
   261	/// digits' prefix, and accumulates each digit as `n * base + digit`, the digit negated
   262	/// under a minus sign, failing where either step overflows; `k`, `m` and `g` then multiply
   263	/// by 1024 once, twice or three times, failing where a product overflows.
   264	fn rust_parse_int64(value: &str) -> Option<i64> {
   265	    let (negative, unsigned) = match value.strip_prefix('-') {
   266	        Some(rest) => (true, rest),
   267	        None => (false, value.strip_prefix('+').unwrap_or(value)),
   268	    };
   269	    let (base, digits) = match unsigned.strip_prefix("0x") {
   270	        Some(hex) if !hex.is_empty() => (16, hex),
   271	        _ if unsigned.starts_with('0') => (8, unsigned),
   272	        _ => (10, unsigned),
   273	    };
   274	    let end = digits
   275	        .find(|c: char| !c.is_digit(base))
   276	        .unwrap_or(digits.len());
   277	    let (digits, suffix) = digits.split_at(end);
   278	    if digits.is_empty() {
   279	        return None;
   280	    }
   281	    let mut n = Some(0_i64);
   282	    for digit in digits.chars() {
   283	        let digit = i64::from(digit.to_digit(base).unwrap());
   284	        let digit = if negative { -digit } else { digit };
   285	        n = n
   286	            .and_then(|n| checked_mul_i64(n, i64::from(base)))
   287	            .and_then(|n| checked_add_i64(n, digit));
   288	    }
   289	    let scale = match suffix {
   290	        "" => 0,
   291	        "k" | "K" => 1,
   292	        "m" | "M" => 2,
   293	        "g" | "G" => 3,
   294	        _ => return None,
   295	    };
   296	    (0..scale).try_fold(n?, |n, _| checked_mul_i64(n, 1024))
   297	}
